-- Source-reviewed on 2026-09-06; synchronized with the offline resource snapshot.
-- Deactivate superseded provider listings without deleting safety-event references.
update public.support_resources set is_active=false where country_code='PH' and (organization_name in ('National Center for Mental Health','HOPELINE PH','In Touch Community Services','Philippine Red Cross','Cavite Center for Mental Health') or organization_name ilike '%red cross%' and phone_number='2919');
